import os,glob,re,json
from collections import deque,Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def solve(g):
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    cs=[]; seen=set(); H,W=len(g),len(g[0])
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); c=[]
                while q:
                    y,x=q.popleft(); c.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            n=(y+dy,x+dx)
                            if 0<=n[0]<H and 0<=n[1]<W and n not in seen and g[n[0]][n[1]]!=bg:
                                seen.add(n); q.append(n)
                cs.append(c)
    # candidate: comp containing a rare-color pixel (color count 1 globally)
    cnt=Counter(x for r in g for x in r)
    cand=[]
    for c in cs:
        rare=[(y,x,g[y][x]) for y,x in c if cnt[g[y][x]]==1]
        if rare: cand.append((c,rare[0]))
    c,_=max(cand,key=lambda t:len(t[0]))
    ys=[r for r,_ in c]; xs=[x for _,x in c]
    r0,r1,x0,x1=min(ys),max(ys),min(xs),max(xs)
    dom=Counter(g[y][x] for y,x in c).most_common(1)[0][0]
    return [[dom if (y,x) in set(c) else bg for x in range(x0,x1+1)] for y in range(r0,r1+1)]
